  /* ---- ray definitions ---- */
  var Q = [-d, h], defs = [];
  if (Math.abs(y1) <= yAp) {
    var M1 = [mx(y1), y1];
    var dir1 = (mode === 'concave') ? [Fx - M1[0], -y1] : [M1[0] - Fx, y1];
    defs.push({ n: 1, inc: [Q, M1], solid: [[M1, extend(M1, dir1[0], dir1[1], box)]],
      dash: (mode === 'convex') ? [[M1, [Fx, 0]]] : [] });
  }
  if (isFinite(y2) && Math.abs(y2) <= yAp) {
    var M2 = [mx(y2), y2];
    var xEnd = Math.max(box.xlo, -d - 0.7);
    defs.push({ n: 2, inc: [Q, M2], solid: [[M2, [xEnd, y2]]],
      dash: (mode === 'convex') ? [[M2, [xi + 0.7, y2]]] : [] });
  }
  if (isFinite(y3) && Math.abs(y3) <= yAp) {
    var M3 = [mx(y3), y3];
    defs.push({ n: 3, inc: [Q, M3], solid: [], retrace: true, ra: true,
      dash: (mode === 'convex') ? [[M3, [M3[0] + 1.08 * (Cx - M3[0]), y3 + 1.08 * (0 - y3)]]] : [] });
  }
  var M4 = [0, 0];
  defs.push({ n: 4, inc: [Q, M4], solid: [[M4, extend(M4, -d, -h, box)]],
    dash: (mode === 'convex') ? [[M4, [xi * 1.3, hi * 1.3]]] : [] });

  /* ---- draw rays ---- */
  defs.forEach(function (r) {
    var c = COL[r.n], sel = state.sel;
    var active = (sel === 0 || sel === r.n);
    var w = lw * (sel === r.n ? 1.9 : 1);
    var op = active ? 1 : 0.16;
    var rg = g.group().css('cursor', 'pointer').opacity(op);
    var ah = unit * 0.24 * (sel === r.n ? 1.25 : 1);

    r.dash.forEach(function (s) { seg(rg, s[0], s[1], c, w * 0.9, true); });
    seg(rg, r.inc[0], r.inc[1], c, w);
    arrowOn(rg, r.inc[0], r.inc[1], r.n === 1 ? 0.66 : 0.5, c, ah);
    numLabel(rg, r.inc[0], r.inc[1], r.n === 1 ? 0.5 : 0.62, 0.42, String(r.n), c);

    r.solid.forEach(function (s) {
      seg(rg, s[0], s[1], c, w);
      arrowOn(rg, s[0], s[1], 0.45, c, ah);
      numLabel(rg, s[0], s[1], 0.72, 0.42, String(r.n), c);
    });
    if (r.retrace) {
      arrowOn(rg, r.inc[0], r.inc[1], 0.82, c, ah, true);
      numLabel(rg, r.inc[0], r.inc[1], 0.9, 0.45, String(r.n), c);
    }
    if (r.ra) {
      var M = r.inc[1], ux = M[0] - r.inc[0][0], uy = M[1] - r.inc[0][1];
      var L = Math.sqrt(ux * ux + uy * uy) || 1; ux /= L; uy /= L;
      var vx = -uy, vy = ux, sgn = (M[1] > 0) ? -1 : 1;
      if (vy * sgn < 0) { vx = -vx; vy = -vy; }
      var q = 0.36;
      var a1 = [M[0] - ux * q, M[1] - uy * q];
      var a2 = [a1[0] + vx * q, a1[1] + vy * q];
      var a3 = [M[0] + vx * q, M[1] + vy * q];
      rg.polyline([a1, a2, a3].map(function (p) { return plotX(p[0]) + ',' + plotY(p[1]); }).join(' '))
        .fill('none').stroke({ color: '#333', width: Math.max(0.7, lw * 0.5) });
    }
    /* invisible hit area */
    var hitAll = [r.inc].concat(r.solid).concat(r.dash);
    hitAll.forEach(function (s) {
      rg.line(plotX(s[0][0]), plotY(s[0][1]), plotX(s[1][0]), plotY(s[1][1]))
        .stroke({ color: '#fff', width: Math.max(8, lw * 6), opacity: 0.01 });
    });
    rg.on('mousemove', function (e) { showTooltip(RULES[r.n].s, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { selectRay(r.n); showPopup('Ray ' + r.n, RULES[r.n].l); });
  });

  /* ---- axis points ---- */
  var rDot = Math.max(1.8, unit * 0.075);
  function dot(wx, wy, col) { return g.circle(rDot * 2).center(plotX(wx), plotY(wy)).fill(col).stroke('none'); }
  dot(Cx, 0, COL.dot); txtAt(g, Cx, 0.62, 'C', '#111', fs, 'middle', true);
  dot(Fx, 0, '#e02b2b'); txtAt(g, Fx, 0.62, 'F', '#111', fs, 'middle', true);
  txtAt(g, mode === 'concave' ? -0.62 : -0.72, mode === 'concave' ? 0.6 : -0.62, 'V', '#111', fs, 'middle', true);

  /* ---- object ---- */
  var ow = Math.max(3, unit * 0.13);
  g.line(plotX(-d), plotY(0), plotX(-d), plotY(h * 0.84)).stroke({ color: COL.obj, width: ow, linecap: 'butt' });
  addArrow(g, -d, h, 0, 0.5, COL.obj, unit * 0.52);
  dot(-d, 0, '#2b6cb0');
  txtAt(g, -d - 0.32, -0.55, 'P', '#111', fs, 'middle', true);
  txtAt(g, -d - 0.42, h + 0.5, 'Q', '#111', fs, 'middle', true);
  txtAt(g, -d - 0.55, h * 0.52, 'Object', '#111', fs * 0.95, 'end');

  /* ---- image ---- */
  var igrp = g.group().css('cursor', 'pointer');
  igrp.line(plotX(xi), plotY(0), plotX(xi), plotY(hi * 0.78)).stroke({ color: COL.img, width: ow * 0.85, linecap: 'butt' });
  addArrow(igrp, xi, hi, 0, (hi > 0 ? 0.4 : -0.4), COL.img, unit * 0.45);
  igrp.circle(rDot * 1.7).center(plotX(xi), plotY(0)).fill('#c0392b').stroke('none');
  igrp.on('mousemove', function (e) {
    showTooltip((mode === 'concave' ? 'Real, inverted image' : 'Virtual, upright image') +
      ' · m = ' + m.toFixed(2), e);
  }).on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(mode === 'concave' ? 'Real image' : 'Virtual image',
        mode === 'concave'
          ? 'All four reflected rays physically pass through Q′, so light really is concentrated there — a screen placed at P′ would catch the inverted image.'
          : 'No reflected ray ever reaches Q′; only the dashed backward extensions meet there. The image is upright, reduced and cannot be caught on a screen.');
    });
  var qlx = xi + (mode === 'concave' ? 0.55 : -0.5), qly = hi + (mode === 'concave' ? -0.45 : 0.5);
  txtAt(g, qlx, qly, 'Q\u2032', '#111', fs, 'middle', true);
  txtAt(g, xi - 0.12, (mode === 'concave' ? 0.6 : -0.58), 'P\u2032', '#111', fs, 'middle', true);

  /* Image leader + label */
  var lx = xi + (mode === 'concave' ? 1.9 : 1.6), ly = hi + (mode === 'concave' ? -1.9 : -2.1);
  if (mode === 'convex') { lx = xi + 1.1; ly = -1.9; }
  var sx0 = plotX(lx), sy0 = plotY(ly + 0.45);
  var ex0 = plotX(xi + (hi > 0 ? 0.12 : 0.12)), ey0 = plotY(hi * 0.82);
  g.path('M ' + sx0 + ' ' + sy0 + ' Q ' + (sx0) + ' ' + ((sy0 + ey0) / 2) + ' ' + ex0 + ' ' + ey0)
    .fill('none').stroke({ color: '#111', width: Math.max(0.8, lw * 0.55) });
  var ang = Math.atan2(ey0 - (sy0 + ey0) / 2, ex0 - sx0);
  addArrow(g, xi + 0.12 + Math.cos(ang) * 0.0, hi * 0.82, Math.cos(ang) * 0.4, -Math.sin(ang) * 0.4, '#111', unit * 0.2);
  txtAt(g, lx, ly, 'Image', '#111', fs * 0.95, 'middle');

  /* ---- eye ---- */
  drawEye(g, clamp(-0.62 * d - 1.0, box.xlo + 1.6, -2.2), -yHalf * 0.6, 0.5);

  /* ---- banner ---- */
  var btxt = (mode === 'concave')
    ? 'Real, inverted image \u2014 the rays actually cross'
    : 'Virtual, upright image \u2014 only the extensions cross';
  var bg = g.group();
  var bt = txtAt(bg, xd[0] + 0.55, yd[1] - 0.75, btxt, mode === 'concave' ? '#0b6b3a' : '#8a4b00', fs * 0.92, 'start');
  var bb = bt.bbox();
  bg.rect(bb.width + fs * 0.7, bb.height + fs * 0.5).move(bb.x - fs * 0.35, bb.y - fs * 0.25)
    .radius(fs * 0.3).fill(mode === 'concave' ? '#eaf7ef' : '#fdf1e2')
    .stroke({ color: mode === 'concave' ? '#9ccfb2' : '#e3bd8a', width: 0.8 }).back();

  /* ---- caption ---- */
  txtAt(g, (xd[0] + xd[1]) / 2, yd[0] + 0.55,
    mode === 'concave' ? '(a) concave mirror' : '(b) convex mirror', '#111', fs * 1.0, 'middle');

  /* info line in UI */
  var info = document.getElementById('imgInfo');
  if (info) {
    info.textContent = 'Object ' + (d / F0).toFixed(1) + 'f in front  ·  image ' +
      Math.abs(di / F0).toFixed(2) + 'f ' + (di > 0 ? 'in front (real)' : 'behind (virtual)') +
      '  ·  m = ' + m.toFixed(2) + (m < 0 ? ' (inverted)' : ' (upright)');
  }
  window.__markRendered();
}

/* ---------- interactions ---------- */
function toggle_mirrorType(on) {
  state.mode = on ? 'convex' : 'concave';
  var v = document.getElementById('mirrorTypeVal');
  if (v) v.textContent = on ? 'Convex' : 'Concave';
  render();
}

function update_objectDistance(v) { state.s = v; render(); }

function selectRay(n) {
  state.sel = (state.sel === n) ? 0 : n;
  updateRuleUI();
  render();
}

function updateRuleUI() {
  for (var k = 0; k <= 4; k++) {
    var b = document.getElementById('rayBtn' + k);
    if (b) b.className = (state.sel === k) ? 'active' : '';
  }
  var rb = document.getElementById('ruleBox');
  if (rb) rb.textContent = state.sel ? RULES[state.sel].l : 'All four rays shown. Any two are enough to locate Q′ — the others confirm it.';
}

function keyIdea() {
  showPopup('Key idea',
    'An image is simply where the rays from a point on the object meet. If they meet in real space the image is real and inverted (concave mirror); if only their backward extensions meet, the image is virtual and upright behind the mirror (convex mirror).');
}

/* ---------- demo steps ---------- */
function goStep(i) {
  i = (i + STEPS.length) % STEPS.length;
  state.step = i;
  var st = STEPS[i];
  state.mode = st.mode;
  state.s = st.s;
  state.sel = st.sel;
  var cb = document.getElementById('mirrorTypeInput');
  if (cb) cb.checked = (state.mode === 'convex');
  var mv = document.getElementById('mirrorTypeVal');
  if (mv) mv.textContent = (state.mode === 'convex') ? 'Convex' : 'Concave';
  var sl = document.getElementById('objectDistanceInput');
  if (sl) sl.value = state.s;
  var so = document.getElementById('objectDistanceVal');
  if (so) so.value = state.s;
  document.getElementById('demoNarration').textContent = st.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (i + 1) + '/' + STEPS.length + ' — ' + st.t;
  updateRuleUI();
  render();
}
function nextStep() { goStep(state.step + 1); }
function prevStep() { goStep(state.step - 1); }

document.addEventListener('fig-resize', function () { render(); });

goStep(0);
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The four principal rays from an object's tip locate its image: for a concave mirror the reflected rays physically converge to a real, inverted image, while for a convex mirror they diverge and only their dashed backward extensions meet at a virtual, upright image behind the mirror.
KEY INSIGHT (what students should walk away understanding): An image is simply where the rays from a point on the object meet — if they meet in real space the image is real and inverted (concave); if only their backward extensions meet, the image is virtual and upright behind the mirror (convex).
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "The four principal rays from an object's tip locate its image: for a concave mirror the reflected rays physically converge to a real, inverted image, while for a convex mirror they diverge and only their dashed backward extensions meet at a virtual, upright image behind the mirror.",
  "figureType": "diagram",
  "elements": [
    "Horizontal optical axis (thin gray line) spanning the panel",
    "Mirror drawn as a pale blue/white curved arc on the right, concave (bulging right) or convex (bulging left) depending on mode",
    "Mirror vertex V labeled where the arc crosses the axis",
    "Focal point F marked as a small red dot on the axis (in front of mirror for concave, behind for convex)",
    "Center of curvature C marked as a small black dot on the axis (in front for concave, behind for convex)",
    "Object: thick red upward arrow at far left, base P (blue dot) on the axis, tip Q labeled above; text label 'Object' to its left",
    "Image: red arrow at P' — short downward (inverted) arrow between C and F for concave; smaller upright arrow behind the mirror between V and F for convex; tip labeled Q'",
    "Curved leader arrow with text label 'Image' pointing to the image arrow tip",
    "Ray 1 (blue): from Q parallel to the axis to the mirror, reflecting through F (concave) or reflecting away with dashed extension back to F behind mirror (convex), numbered '1' with mid-line arrowheads",
    "Ray 2 (red): from Q along a line through F to the mirror, reflecting parallel to the axis back to the left; numbered '2'",
    "Ray 3 (purple): from Q along a line through C, striking the mirror perpendicularly and retracing itself; small right-angle square drawn at the mirror surface; numbered '3'",
    "Ray 4 (green): from Q to the vertex V, reflecting symmetrically about the axis; numbered '4'",
    "Dashed continuation segments (convex mode) in matching colors showing virtual backward extensions converging at Q'",
    "Small hand-drawn eye at lower left looking toward the mirror",
    "Panel caption label '(a) concave' or '(b) convex'",
    "Ray legend / numbered color key listing the four ray rules",
    "Text annotation reading 'Real image — rays actually cross' or 'Virtual image — only extensions cross'"
  ],
  "interactions": [
    {
      "id": "mirrorType",
      "type": "toggle",
      "teaches": "That a concave mirror converges reflected rays into a real inverted image in front of it, while a convex mirror diverges them so only the dashed backward extensions meet, producing a virtual upright image behind the mirror.",
      "label": "Mirror type",
      "options": [
        "Concave",
        "Convex"
      ],
      "default": "Concave"
    },
    {
      "id": "selectRay",
      "type": "click",
      "teaches": "The individual construction rule behind each numbered principal ray, isolated from the crowded crossing pattern: parallel-in→through-F, through-F→parallel-out, through-C→retrace, and vertex→equal angles.",
      "teachesDetail": "Clicking a ray's line or its number brightens that ray from Q to the mirror and along its reflected/extended path, dims the other three, and shows its rule text."
    },
    {
      "id": "objectDistance",
      "type": "slider",
      "teaches": "How image position, size, and orientation depend on where the object sits relative to F and C — inverted and shrinking beyond C, enlarging between C and F, and always small, upright and virtual for the convex mirror.",
      "label": "Object distance from mirror (in focal lengths)",
      "range": [
        1.2,
        5,
        0.1
      ],
      "default": 3
    }
  ],
  "demo_steps": [
    {
      "title": "The concave construction",
      "narration": "A concave mirror with object arrow PQ on the left. All four principal rays leave the tip Q and, after reflection, actually cross at Q' between C and F — a real, inverted image the eye can see in space.",
      "state": {
        "mirrorType": "Concave",
        "objectDistance": 3
      }
    },
    {
      "title": "Isolate one ray rule",
      "narration": "Click ray 1: the blue ray travels parallel to the axis and must reflect through F. Clicking rays 2, 3, and 4 in turn shows the through-F, through-C, and vertex rules — any two of them are enough to fix Q'.",
      "state": {
        "mirrorType": "Concave",
        "objectDistance": 3
      }
    },
    {
      "title": "Slide the object inward",
      "narration": "Move the object from far away toward F. The real image slides outward past C and grows, staying inverted — object position relative to F controls both size and location.",
      "state": {
        "mirrorType": "Concave",
        "objectDistance": 1.4
      }
    },
    {
      "title": "Switch to the convex mirror",
      "narration": "Flip the mirror. Now the same four rays spread apart after reflection; nothing converges in front of the mirror. Only their dashed backward extensions meet, at a virtual Q' behind the surface.",
      "state": {
        "mirrorType": "Convex",
        "objectDistance": 3
      }
    },
    {
      "title": "Virtual image stays tame",
      "narration": "Slide the object anywhere along the axis: the convex image remains upright, reduced, and trapped between V and F — a virtual image no screen can catch.",
      "state": {
        "mirrorType": "Convex",
        "objectDistance": 1.6
      }
    }
  ],
  "keyInsight": "An image is simply where the rays from a point on the object meet — if they meet in real space the image is real and inverted (concave); if only their backward extensions meet, the image is virtual and upright behind the mirror (convex).",
  "reconstructionNotes": "Single wide panel (with the toggle swapping mirror geometry rather than stacking two panels), optical axis a thin gray horizontal line about mid-height, mirror as a pale blue-white curved arc with slight thickness on the right side. Object is a thick salmon-red upward arrow at the far left with base P (blue dot) on the axis and serif-italic label Q at the tip, 'Object' text to its left. Mark C (black dot) and F (red dot) on the axis with italic labels; for concave both lie left of the mirror with C farther out, for convex both lie right of (behind) the arc with C farthest. Four rays in distinct saturated colors: ray 1 teal-blue, ray 2 red, ray 3 purple, ray 4 olive-green, each with bold colored number placed mid-segment and small arrowheads showing propagation direction. Ray 3 gets a small right-angle square where it meets the mirror. In convex mode, reflected rays diverge upward/leftward and their backward extensions are drawn as dashed lines of the same color converging behind the mirror. Image arrow is a lighter red/pink arrow: downward (inverted) between C and F in concave mode, upright and shorter behind the mirror in convex mode, with base P' on the axis and tip Q', plus a curved black leader arrow labeled 'Image'. A small line-art eye sits at the lower left looking rightward. Selected ray renders at full opacity and double stroke weight; unselected rays drop to about 20% opacity. Include a short annotation banner that reads 'Real, inverted image' or 'Virtual, upright image' matching the mode.",
  "reconstructionNotes_extra": "Keep ray endpoints computed from the object position slider so all four rays always intersect consistently at the same Q'."
}

