  var dx = to[0] - from[0], dy = to[1] - from[1], L = hyp(dx, dy) || 1;
  var st = [from[0] + dx / L * 0.55, from[1] + dy / L * 0.55];
  var x1 = plotX(st[0]), y1 = plotY(st[1]), x2 = plotX(to[0]), y2 = plotY(to[1]);
  var sdx = x2 - x1, sdy = y2 - y1, sL = hyp(sdx, sdy) || 1;
  var cx = (x1 + x2) / 2 - sdy / sL * bend, cy = (y1 + y2) / 2 + sdx / sL * bend;
  g.path('M ' + x1 + ' ' + y1 + ' Q ' + cx + ' ' + cy + ' ' + x2 + ' ' + y2)
    .fill('none').stroke({ color: '#1a1a1a', width: Math.max(0.9, lw * 0.6) });
  var ax = x2 - cx, ay = y2 - cy, aL = hyp(ax, ay) || 1;
  var sz = Math.max(5, unit * 0.2), a = Math.atan2(ay, ax);
  var p = [[x2, y2],
  [x2 - Math.cos(a) * sz + Math.cos(a + Math.PI / 2) * sz * 0.44, y2 - Math.sin(a) * sz + Math.sin(a + Math.PI / 2) * sz * 0.44],
  [x2 - Math.cos(a) * sz - Math.cos(a + Math.PI / 2) * sz * 0.44, y2 - Math.sin(a) * sz - Math.sin(a + Math.PI / 2) * sz * 0.44]];
  g.polygon(p.map(function (q) { return q[0] + ',' + q[1]; }).join(' ')).fill('#1a1a1a');
}

function drawEye(g, wx, wy, sz) {
  var cx = plotX(wx), cy = plotY(wy), u = sz * unit, w = Math.max(1, unit * 0.035);
  function P(a, b) { return (cx + a * u) + ',' + (cy + b * u); }
  var eg = g.group().css('cursor', 'pointer');
  eg.path('M ' + P(-1.25, 0.15) + ' C ' + P(-0.7, -0.7) + ' ' + P(0.55, -0.9) + ' ' + P(1.3, -0.15) +
    ' C ' + P(0.6, 0.65) + ' ' + P(-0.6, 0.8) + ' ' + P(-1.25, 0.15) + ' Z')
    .fill('#fff').stroke({ color: '#222', width: w });
  eg.circle(u * 0.44).center(cx + 0.78 * u, cy - 0.16 * u).fill('#222');
  [[[-1.22, 0.1], [-1.72, 0.3]], [[-0.95, -0.45], [-1.3, -0.85]], [[-0.45, -0.72], [-0.6, -1.2]], [[0.15, -0.78], [0.2, -1.25]]]
    .forEach(function (s) {
      eg.line(cx + s[0][0] * u, cy + s[0][1] * u, cx + s[1][0] * u, cy + s[1][1] * u)
        .stroke({ color: '#222', width: w, linecap: 'round' });
    });
  eg.on('mousemove', function (e) { showTooltip('The observer looks toward the mirror and sees the image', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The observer', 'The eye intercepts the reflected rays. Whether they truly crossed (real image) or only appear to come from a point behind the mirror (virtual image), the brain projects the tip of the object back to Q′.');
    });
  return eg;
}

/* ───────── main render ───────── */
function render() {
  var mode = state.mode, d = state.s * F0, h = H0;
  var f = (mode === 'concave') ? F0 : -F0;
  var Fx = -f, Cx = 2 * Fx;
  var di = d * f / (d - f), xi = -di, m = -di / d, hi = m * h;

  var y1 = h;
  var y2 = (Math.abs(d + Fx) < 1e-6) ? NaN : h * Fx / (d + Fx);
  var y3 = (Math.abs(d + Cx) < 1e-6) ? NaN : h * Cx / (d + Cx);
  var cap = 3.0 * h;
  var use2 = isFinite(y2) && Math.abs(y2) <= cap;
  var use3 = isFinite(y3) && Math.abs(y3) <= cap;
  var maxHit = h;
  if (use2) maxHit = Math.max(maxHit, Math.abs(y2));
  if (use3) maxHit = Math.max(maxHit, Math.abs(y3));

  var yAp = Math.max(h * 1.35, maxHit * 1.15);
  var yNeed = Math.max(yAp + 0.8, Math.min(Math.abs(hi) + 1.15, yAp * 1.55 + 1.2), h + 1.3);
  var xlo = Math.min(-d - 1.85, xi - 1.8);
  var xhi = (mode === 'concave') ? 0.85 : (Cx + 1.15);

  applyFrame(xlo, xhi, yNeed);
  draw.clear();
  var g = draw.group();

  var xd = _plotFrame.xDomain, yd = _plotFrame.yDomain;
  var box = { xlo: xd[0] + 0.3, xhi: xd[1] - 0.3, ylo: yd[0] + 1.0, yhi: yd[1] - 0.85 };
  var Rd = 2.8 * yAp;
  function mx(y) {
    var s = Math.sqrt(Math.max(0, Rd * Rd - y * y));
    return (mode === 'concave') ? (s - Rd) : (Rd - s);
  }

  var obs = [], i, y;
  obs.push([[xd[0], 0], [xd[1], 0]]);

  /* ---- axis ---- */
  g.line(plotX(xd[0] + 0.1), plotY(0), plotX(xd[1] - 0.1), plotY(0))
    .stroke({ color: COL.axis, width: Math.max(0.8, unit * 0.022) });

  /* ---- mirror arc ---- */
  var arcPts = [];
  for (i = 0; i <= 64; i++) { y = -yAp + 2 * yAp * i / 64; arcPts.push([mx(y), y]); }
  for (i = 0; i < arcPts.length - 1; i++) obs.push([arcPts[i], arcPts[i + 1]]);
  var ps = arcPts.map(function (p) { return plotX(p[0]) + ',' + plotY(p[1]); }).join(' ');
  var mgrp = g.group().css('cursor', 'pointer');
  mgrp.polyline(ps).fill('none').stroke({ color: COL.mirEdge, width: Math.max(2.2, unit * 0.22), linecap: 'round' });
  mgrp.polyline(ps).fill('none').stroke({ color: COL.mir, width: Math.max(1.6, unit * 0.18), linecap: 'round' });
  mgrp.polyline(arcPts.map(function (p) {
    return (plotX(p[0]) + (mode === 'concave' ? -unit * 0.045 : unit * 0.045)) + ',' + plotY(p[1]);
  }).join(' ')).fill('none').stroke({ color: COL.mirHi, width: Math.max(0.9, unit * 0.06), linecap: 'round' });
  mgrp.on('mousemove', function (e) {
    showTooltip(mode === 'concave' ? 'Concave mirror: hollow side faces the object' : 'Convex mirror: bulging side faces the object', e);
  }).on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(mode === 'concave' ? 'Concave mirror' : 'Convex mirror',
        mode === 'concave'
          ? 'Its centre of curvature C and focal point F lie in front of the surface, so reflected rays bend toward the axis and can genuinely cross.'
          : 'Its centre of curvature C and focal point F lie behind the surface, so reflected rays always spread apart; only their backward extensions meet.');
    });

  /* ---- build ray paths ---- */
  var Q = [-d, h], rays = [], raM3 = null;

  var M1 = [mx(y1), y1];
  var p1 = [{ a: Q, b: M1, ar: [[0.62, 0]], nm: [[0.42, 1]] }];
  if (mode === 'concave') {
    var e1 = extend(M1, Fx - M1[0], -y1, box);
    p1.push({ a: M1, b: e1, ar: [[0.33, 0], [0.82, 0]], nm: [[0.62, 1]] });
  } else {
    var d1x = M1[0] - Fx, d1y = y1;
    p1.push({ a: M1, b: extend(M1, d1x, d1y, box), ar: [[0.5, 0]], nm: [[0.78, 1]] });
    p1.push({ a: M1, b: [M1[0] + 1.14 * (Fx - M1[0]), y1 + 1.14 * (0 - y1)], dash: true });
  }
  rays.push({ n: 1, parts: p1 });

  if (use2) {
    var M2 = [mx(y2), y2];
    var xEnd = Math.max(box.xlo, -d - 1.35);
    var p2 = [{ a: Q, b: M2, ar: [[0.55, 0]], nm: [[0.34, 1]] },
    { a: M2, b: [xEnd, y2], ar: [[0.5, 0]], nm: [[0.26, 1]] }];
    if (mode === 'convex') p2.push({ a: M2, b: [xi + 1.0, y2], dash: true });
    rays.push({ n: 2, parts: p2 });
  }

  if (use3) {
    var M3 = [mx(y3), y3]; raM3 = M3;
    var back = extend(M3, Q[0] - M3[0], Q[1] - M3[1], box);
    var p3 = [{ a: Q, b: M3, ar: [[0.5, 0]], nm: [[0.34, 1]] },
    { a: M3, b: back, ar: [[0.3, 0], [0.78, 0]], nm: [[0.62, -1]] }];
    if (mode === 'convex') p3.push({ a: M3, b: [Cx, 0], dash: true });
    rays.push({ n: 3, parts: p3 });
  }

  var M4 = [0, 0];
  var p4 = [{ a: Q, b: M4, ar: [[0.5, 0]], nm: [[0.32, 1]] },
  { a: M4, b: extend(M4, -d, -h, box), ar: [[0.5, 0]], nm: [[0.72, 1]] }];
  if (mode === 'convex') p4.push({ a: M4, b: [xi * 1.5, hi * 1.5], dash: true });
  rays.push({ n: 4, parts: p4 });

  rays.forEach(function (r) { r.parts.forEach(function (p) { obs.push([p.a, p.b]); }); });
  obs.push([[-d, 0], [-d, h]]);

  /* ---- draw rays ---- */
  rays.forEach(function (r) {
    var c = COL[r.n], sel = state.sel, active = (sel === 0 || sel === r.n);
    var w = lw * (sel === r.n ? 1.95 : 1);
    var rg = g.group().css('cursor', 'pointer').opacity(active ? 1 : 0.17);
    var ah = unit * 0.24 * (sel === r.n ? 1.25 : 1);
    r.parts.forEach(function (p) {
      if (p.dash) { seg(rg, p.a, p.b, c, w * 0.92, true); return; }
      seg(rg, p.a, p.b, c, w);
    });
    r.parts.forEach(function (p) {
      if (p.dash) return;
      (p.ar || []).forEach(function (t) { arrowOn(rg, p.a, p.b, t[0], c, ah, t[1] < 0); });
      (p.nm || []).forEach(function (t) { numLabel(rg, p.a, p.b, t[0], String(r.n), c, t[1]); });
    });
    if (r.n === 3 && raM3) {
      var M = raM3, ux = M[0] - Q[0], uy = M[1] - Q[1], L = hyp(ux, uy) || 1;
      ux /= L; uy /= L;
      var vx = -uy, vy = ux, sgn = (M[1] > 0) ? -1 : 1;
      if (vy * sgn < 0) { vx = -vx; vy = -vy; }
      var q = Math.max(0.24, (fs * 0.55) / unit);
      var a1 = [M[0] - ux * q, M[1] - uy * q];
      var a2 = [a1[0] + vx * q, a1[1] + vy * q];
      var a3 = [M[0] + vx * q, M[1] + vy * q];
      rg.polyline([a1, a2, a3].map(function (p) { return plotX(p[0]) + ',' + plotY(p[1]); }).join(' '))
        .fill('none').stroke({ color: '#333', width: Math.max(0.8, lw * 0.5) });
    }
    r.parts.forEach(function (p) {
      rg.line(plotX(p.a[0]), plotY(p.a[1]), plotX(p.b[0]), plotY(p.b[1]))
        .stroke({ color: '#fff', width: Math.max(9, lw * 6), opacity: 0.01 });
    });
    rg.on('mousemove', function (e) { showTooltip(RULES[r.n].s, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { selectRay(r.n); showPopup('Ray ' + r.n, RULES[r.n].l); });
  });

  /* ---- axis dots + staggered axis labels ---- */
  var rDot = Math.max(2.0, unit * 0.072);
  function dot(wx, wy, col, rr) { g.circle((rr || rDot) * 2).center(plotX(wx), plotY(wy)).fill(col).stroke('none'); }
  dot(Cx, 0, '#111');
  dot(Fx, 0, '#e02b2b');
  dot(-d, 0, '#2b6cb0');
  dot(xi, 0, '#c0392b', rDot * 0.9);

  var items = [
    { x: -d, text: 'P', pref: -1 },
    { x: Cx, text: 'C', pref: 1 },
    { x: Fx, text: 'F', pref: 1 },
    { x: xi, text: 'P\u2032', pref: (mode === 'concave') ? 1 : -1 },
    { x: (mode === 'concave') ? -0.48 : -0.5, text: 'V', pref: (mode === 'concave') ? 1 : -1 }
  ];
  items.sort(function (A, B) { return A.x - B.x; });
  var lastA = -1e9, lastB = -1e9, minGap = (fs * 1.75) / unit, off = (fs * 0.82) / unit;
  items.forEach(function (it) {
    var side = it.pref, bump = 0;
    var lastSame = (side > 0) ? lastA : lastB, lastOther = (side > 0) ? lastB : lastA;
    if (it.x - lastSame < minGap) {
      if (it.x - lastOther >= minGap) { side = -side; } else { bump = 1; }
    }
    var yy = (side > 0) ? off * (1.05 + bump * 1.2) : -off * (1.12 + bump * 1.2);
    txtAt(g, it.x, yy, it.text, '#111', fs, 'middle', true);
    if (side > 0) lastA = it.x; else lastB = it.x;
    obs.push([[it.x - 0.28, yy], [it.x + 0.28, yy]]);
  });

  /* ---- object ---- */
  var ow = Math.max(3.2, unit * 0.12);
  g.line(plotX(-d), plotY(0), plotX(-d), plotY(h * 0.85)).stroke({ color: COL.obj, width: ow, linecap: 'butt' });
  addArrow(g, -d, h, 0, 0.45, COL.obj, unit * 0.5);
  txtAt(g, -d - 0.2, h + 0.52, 'Q', '#111', fs, 'end', true);
  txtAt(g, -d - 0.32, h * 0.5, 'Object', '#111', fs * 0.95, 'end');
  obs.push([[-d - 1.5, h * 0.5], [-d - 0.3, h * 0.5]]);

  /* ---- image ---- */
  var lim = (hi < 0) ? (box.ylo + 0.75) : (box.yhi - 0.75);
  var hiD = hi, clipped = false;
  if (Math.abs(hi) > Math.abs(lim)) { hiD = lim; clipped = true; }
  var igrp = g.group().css('cursor', 'pointer');
  igrp.line(plotX(xi), plotY(0), plotX(xi), plotY(hiD * (clipped ? 1 : 0.8)))
    .stroke({ color: COL.img, width: ow * 0.88, linecap: 'butt' });
  if (!clipped) addArrow(igrp, xi, hiD, 0, (hiD > 0 ? 0.36 : -0.36), COL.img, unit * 0.44);
  igrp.on('mousemove', function (e) {
    showTooltip((mode === 'concave' ? 'Real, inverted image' : 'Virtual, upright image') + ' · m = ' + m.toFixed(2), e);
  }).on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(mode === 'concave' ? 'Real image' : 'Virtual image',
        mode === 'concave'
          ? 'All the reflected rays physically pass through Q′, so light really is concentrated there — a screen placed at P′ would catch the inverted image.'
          : 'No reflected ray ever reaches Q′; only the dashed backward extensions meet there. The image is upright, reduced and cannot be caught on a screen.');
    });
  obs.push([[xi, 0], [xi, hiD]]);

  var qo = (fs * 0.85) / unit;
  var qCand = [[xi + qo * 1.5, hiD - qo], [xi - qo * 1.5, hiD - qo],
  [xi + qo * 1.5, hiD + qo], [xi - qo * 1.5, hiD + qo]];
  var qp = bestSpot(qCand, obs);
  txtAt(g, qp[0], qp[1], 'Q\u2032', '#111', fs, 'middle', true);
  obs.push([[qp[0] - 0.28, qp[1]], [qp[0] + 0.28, qp[1]]]);

  /* ---- 'Image' label in clear space, with curved leader ---- */
  var cands = [], cx, cy;
  var xLoC, xHiC, yLoC, yHiC;
  if (mode === 'concave') {
    xLoC = xi + 0.7; xHiC = Math.min(box.xhi - 1.0, xi + 3.1); yLoC = hiD - 2.8; yHiC = hiD - 0.9;
  } else {
    xLoC = xi - 1.0; xHiC = Math.min(box.xhi - 0.9, xi + 2.4); yLoC = -2.9; yHiC = -1.0;
  }
  for (cx = xLoC; cx <= xHiC + 1e-6; cx += Math.max(0.2, (xHiC - xLoC) / 6)) {
    for (cy = yLoC; cy <= yHiC + 1e-6; cy += Math.max(0.2, (yHiC - yLoC) / 5)) {
      if (cy < box.ylo + 0.4 || cy > box.yhi - 0.4) continue;
      if (mode === 'concave' && cx > mx(cy) - 0.85) continue;
      cands.push([cx, cy]);
    }
  }
  if (!cands.length) cands.push([xi + 1.2, hiD - 1.4]);
  var lp = bestSpot(cands, obs);
  var target = [xi + (lp[0] > xi ? 0.12 : -0.12), hiD * 0.82];
  leader(g, lp, target, unit * 0.45);
  txtAt(g, lp[0], lp[1], 'Image', '#111', fs * 0.95, 'middle');
  obs.push([[lp[0] - 0.6, lp[1]], [lp[0] + 0.6, lp[1]]]);

  /* ---- eye in clear space, lower left ---- */
  var eCands = [], exLo = box.xlo + 1.2, exHi = (mode === 'concave') ? -1.6 : -0.8;
  for (cx = exLo; cx <= exHi; cx += Math.max(0.25, (exHi - exLo) / 8)) {
    for (cy = -yd[1] * 0.85 + 0.6; cy <= -0.9; cy += Math.max(0.25, (yd[1] * 0.85 - 1.5) / 5)) {
      eCands.push([cx, cy]);
    }
  }
  if (!eCands.length) eCands.push([box.xlo + 1.4, -yd[1] * 0.6]);
  var ep = bestSpot(eCands, obs);
  drawEye(g, ep[0], ep[1], Math.min(0.55, Math.max(0.3, yd[1] * 0.1)));

  /* ---- soft status text + caption ---- */
  var btxt = (mode === 'concave')
    ? 'real, inverted image — the rays actually cross'
    : 'virtual, upright image — only the extensions cross';
  var halfW = (btxt.length * fs * 0.40) / unit / 2;
  var bCands = [[xd[0] + 0.45 + halfW, yd[1] - 0.6], [xd[1] - 0.45 - halfW, yd[1] - 0.6],
  [xd[0] + 0.45 + halfW, yd[1] - 1.5], [xd[1] - 0.45 - halfW, yd[1] - 1.5]];
  var bp = bestSpot(bCands, obs);
  txtAt(g, bp[0], bp[1], btxt, mode === 'concave' ? '#2c6e49' : '#8a5000', fs * 0.82, 'middle');

  txtAt(g, (xd[0] + xd[1]) / 2, yd[0] + 0.45,
    mode === 'concave' ? '(a) concave mirror' : '(b) convex mirror', '#111', fs * 0.95, 'middle');

  /* ---- UI info ---- */
  var info = document.getElementById('imgInfo');
  if (info) {
    var msg = 'Object ' + (d / F0).toFixed(1) + 'f in front  ·  image ' +
      Math.abs(di / F0).toFixed(2) + 'f ' + (di > 0 ? 'in front (real)' : 'behind (virtual)') +
      '  ·  m = ' + m.toFixed(2) + (m < 0 ? ' (inverted)' : ' (upright)');
    var miss = [];
    if (!use2) miss.push('2');
    if (!use3) miss.push('3');
    if (miss.length) msg += '  —  ray ' + miss.join(' & ') + ' would strike far outside this finite mirror, so it is not drawn.';
    info.textContent = msg;
  }
  window.__markRendered();
}

/* ───────── interactions ───────── */
function toggle_mirrorType(on) {
  state.mode = on ? 'convex' : 'concave';
  var v = document.getElementById('mirrorTypeVal');
  if (v) v.textContent = on ? 'Convex' : 'Concave';
  render();
}
function update_objectDistance(v) { state.s = v; render(); }
function selectRay(n) { state.sel = (state.sel === n) ? 0 : n; updateRuleUI(); render(); }

function updateRuleUI() {
  for (var k = 0; k <= 4; k++) {
    var b = document.getElementById('rayBtn' + k);
    if (b) b.className = (state.sel === k) ? 'active' : '';
  }
  var rb = document.getElementById('ruleBox');
  if (rb) rb.textContent = state.sel ? RULES[state.sel].l
    : 'All rays shown. Any two are enough to locate Q′ — the others confirm it.';
}

function keyIdea() {
  showPopup('Key idea',
    'An image is simply where the rays from a point on the object meet. If they meet in real space the image is real and inverted (concave mirror); if only their backward extensions meet, the image is virtual and upright behind the mirror (convex mirror).');
}

/* ───────── demo steps ───────── */
function goStep(i) {
  i = (i + STEPS.length) % STEPS.length;
  state.step = i;
  var st = STEPS[i];
  state.mode = st.mode; state.s = st.s; state.sel = st.sel;
  var cb = document.getElementById('mirrorTypeInput');
  if (cb) cb.checked = (state.mode === 'convex');
  var mv = document.getElementById('mirrorTypeVal');
  if (mv) mv.textContent = (state.mode === 'convex') ? 'Convex' : 'Concave';
  var sl = document.getElementById('objectDistanceInput');
  if (sl) sl.value = state.s;
  var so = document.getElementById('objectDistanceVal');
  if (so) so.value = state.s;
  document.getElementById('demoNarration').textContent = st.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (i + 1) + '/' + STEPS.length + ' — ' + st.t;
  updateRuleUI();
  render();
}
function nextStep() { goStep(state.step + 1); }
function prevStep() { goStep(state.step - 1); }

document.addEventListener('fig-resize', function () { render(); });
goStep(0);
// @FIGURE_CODE_END

