    p1.push({ a: M1, b: mv(M1, Qp, 1.9), ar: [0.3, 0.8], nf: [0.58, 0.72, 0.88, 0.44] });
  } else {
    p1.push({ a: M1, b: dirTo(M1, [2 * M1[0] - Fp[0], 2 * M1[1] - Fp[1]], far * 0.75), ar: [0.45], nf: [0.3, 0.46, 0.62] });
    p1.push({ a: M1, b: mv(M1, Fp, 1.12), dash: true });
  }
  rays.push({ n: 1, parts: p1 });

  if (use2) {
    var p2 = [{ a: Q, b: M2, ar: [0.5], nf: [0.3, 0.42, 0.56, 0.68] },
    { a: M2, b: [-d - 0.75, y2], ar: [0.45], nf: [0.24, 0.38, 0.52, 0.66] }];
    if (mode === 'convex') p2.push({ a: M2, b: mv(M2, Qp, 1.32), dash: true });
    rays.push({ n: 2, parts: p2 });
  }

  if (use3) {
    var p3 = [{ a: Q, b: M3, ar: [0.45], nf: [0.26, 0.38, 0.52, 0.64] },
    { a: M3, b: mv(M3, Q, 1.3), ar: [0.3, 0.74], nf: [0.5, 0.64, 0.8, 0.38] }];
    if (mode === 'convex') p3.push({ a: M3, b: mv(M3, Cp, 1.05), dash: true });
    rays.push({ n: 3, parts: p3, rm: M3 });
  }

  var p4 = [{ a: Q, b: V, ar: [0.5], nf: [0.34, 0.46, 0.6, 0.72] }];
  if (mode === 'concave') {
    p4.push({ a: V, b: mv(V, Qp, 1.95), ar: [0.35, 0.82], nf: [0.58, 0.74, 0.9, 0.46] });
  } else {
    p4.push({ a: V, b: dirTo(V, [-d, -h], far * 0.5), ar: [0.5], nf: [0.34, 0.5, 0.68] });
    p4.push({ a: V, b: mv(V, Qp, 1.45), dash: true });
  }
  rays.push({ n: 4, parts: p4 });

  /* ---- frame (two passes so text pads use the real font size) ---- */
  var xiD = (mode === 'concave') ? Math.max(xi, -(d + 5)) : xi;
  var x0 = Math.min(-d, xiD) - 0.35, x1 = (mode === 'concave') ? 0.85 : (Cx + 0.6);
  var yTop = Math.max(yAp, h + 0.3, (hi > 0 ? hi + 0.5 : 0));
  var yBot = -Math.max(yAp, (hi < 0 ? Math.min(-hi + 0.5, yAp * 1.9 + 1.6) : 0));
  applyFrame(x0, x1, yBot, yTop);
  var pL = (fs * 4.8) / unit, pR = (fs * 2.3) / unit, pT = (fs * 1.6) / unit, pB = (fs * 2.7) / unit;
  applyFrame(x0 - pL, x1 + pR, yBot - pB, yTop + pT);

  draw.clear();
  placedBoxes = []; obstacles = [];
  var g = draw.group();
  var xd = _plotFrame.xDomain, yd = _plotFrame.yDomain;
  var box = { xlo: xd[0] + 0.14, xhi: xd[1] - 0.14, ylo: yd[0] + 0.14, yhi: yd[1] - 0.14 };
  var lblBox = { xlo: xd[0] + 0.1, xhi: xd[1] - 0.1, ylo: yd[0] + (fs * 1.6) / unit, yhi: yd[1] - 0.1 };

  /* clip every ray segment to the visible frame */
  rays.forEach(function (r) {
    var kept = [];
    r.parts.forEach(function (p) {
      var c = clipSeg(p.a, p.b, box);
      if (!c) return;
      p.a = c[0]; p.b = c[1];
      kept.push(p);
    });
    r.parts = kept;
  });

  /* ---- axis ---- */
  g.line(plotX(box.xlo), plotY(0), plotX(box.xhi), plotY(0))
    .stroke({ color: COL.axis, width: Math.max(0.8, unit * 0.022) });
  obstacles.push([[box.xlo, 0], [box.xhi, 0]]);

  /* ---- mirror ---- */
  var arcPts = [], i, y;
  for (i = 0; i <= 72; i++) { y = -yAp + 2 * yAp * i / 72; arcPts.push([mxf(y), y]); }
  drawMirror(g, arcPts, mode, Xc0, Rd);
  for (i = 0; i < arcPts.length - 1; i++) obstacles.push([arcPts[i], arcPts[i + 1]]);

  /* ---- rays ---- */
  rays.forEach(function (r) { r.parts.forEach(function (p) { obstacles.push([p.a, p.b]); }); });
  obstacles.push([[-d, 0], [-d, h]]);

  var rayGroups = {};
  rays.forEach(function (r) {
    var c = COL[r.n], sel = state.sel, active = (sel === 0 || sel === r.n);
    var w = lw * (sel === r.n ? 1.95 : 1);
    var rg = g.group().css('cursor', 'pointer').opacity(active ? 1 : 0.16);
    rayGroups[r.n] = active ? 1 : 0.16;
    var ah = unit * 0.23 * (sel === r.n ? 1.25 : 1);
    r.parts.forEach(function (p) { seg(rg, p.a, p.b, c, p.dash ? w * 0.92 : w, !!p.dash); });
    r.parts.forEach(function (p) {
      if (p.dash) return;
      (p.ar || []).forEach(function (t) { arrowOn(rg, p.a, p.b, t, c, ah); });
    });
    if (r.rm) {
      var M = r.rm, nx = (M[0] - Xc0) / Rd, ny = M[1] / Rd;
      var tx = -ny, ty = nx;
      if ((M[1] > 0 && ty > 0) || (M[1] <= 0 && ty < 0)) { tx = -tx; ty = -ty; }
      var ux = Q[0] - M[0], uy = Q[1] - M[1], uL = hyp(ux, uy) || 1; ux /= uL; uy /= uL;
      var q = Math.max(0.2, (fs * 0.48) / unit);
      var a1 = [M[0] + ux * q, M[1] + uy * q];
      var a3 = [M[0] + tx * q, M[1] + ty * q];
      var a2 = [a1[0] + tx * q, a1[1] + ty * q];
      rg.polyline([a1, a2, a3].map(function (p) { return plotX(p[0]) + ',' + plotY(p[1]); }).join(' '))
        .fill('none').stroke({ color: '#333', width: Math.max(0.8, lw * 0.5) });
    }
    r.parts.forEach(function (p) {
      rg.line(plotX(p.a[0]), plotY(p.a[1]), plotX(p.b[0]), plotY(p.b[1]))
        .stroke({ color: '#fff', width: Math.max(9, lw * 6), opacity: 0.01 });
    });
    rg.on('mousemove', function (e) { showTooltip(RULES[r.n].s, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { selectRay(r.n); showPopup('Ray ' + r.n, RULES[r.n].l); });
  });

  /* ---- axis dots ---- */
  var rDot = Math.max(2.0, unit * 0.068);
  function dot(wx, wy, col, rr) { g.circle((rr || rDot) * 2).center(plotX(wx), plotY(wy)).fill(col).stroke('none'); }
  if (inBox(Cp, box)) dot(Cx, 0, '#111');
  if (inBox(Fp, box)) dot(Fx, 0, '#e02b2b');
  dot(-d, 0, '#2b6cb0');
  if (xi > box.xlo && xi < box.xhi) dot(xi, 0, '#c0392b', rDot * 0.9);

  /* ---- object ---- */
  var ow = Math.max(3.2, unit * 0.115);
  g.line(plotX(-d), plotY(0), plotX(-d), plotY(h * 0.84)).stroke({ color: COL.obj, width: ow, linecap: 'butt' });
  addArrow(g, -d, h, 0, 0.45, COL.obj, unit * 0.48);

  /* ---- image ---- */
  var igrp = g.group().css('cursor', 'pointer');
  var imgSeg = clipSeg([xi, 0], [xi, hi * 0.82], box);
  if (imgSeg) {
    igrp.line(plotX(imgSeg[0][0]), plotY(imgSeg[0][1]), plotX(imgSeg[1][0]), plotY(imgSeg[1][1]))
      .stroke({ color: COL.img, width: ow * 0.88, linecap: 'butt' });
  }
  var tipVisible = inBox(Qp, box);
  if (tipVisible) addArrow(igrp, xi, hi, 0, (hi > 0 ? 0.36 : -0.36), COL.img, unit * 0.42);
  igrp.on('mousemove', function (e) {
    showTooltip((mode === 'concave' ? 'Real, inverted image' : 'Virtual, upright image') + ' · m = ' + m.toFixed(2), e);
  }).on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup(mode === 'concave' ? 'Real image' : 'Virtual image',
        mode === 'concave'
          ? 'All the reflected rays physically pass through Q′, so light really is concentrated there — a screen placed at P′ would catch the inverted image.'
          : 'No reflected ray ever reaches Q′; only the dashed backward extensions meet there. The image is upright, reduced and cannot be caught on a screen.');
    });
  if (imgSeg) obstacles.push([imgSeg[0], imgSeg[1]]);

  /* ---- eye (lower-left clear space) ---- */
  var eCands = [], cx, cy;
  var exLo = box.xlo + 1.1, exHi = (mode === 'concave') ? -1.5 : -0.8;
  var eyLo = box.ylo + 0.9, eyHi = -0.9;
  if (exHi > exLo && eyHi > eyLo) {
    for (cx = exLo; cx <= exHi; cx += Math.max(0.25, (exHi - exLo) / 8)) {
      for (cy = eyLo; cy <= eyHi; cy += Math.max(0.25, (eyHi - eyLo) / 5)) eCands.push([cx, cy]);
    }
  }
  if (!eCands.length) eCands.push([box.xlo + 1.2, box.ylo + 1.0]);
  var ebest = eCands[0], ebv = -1;
  eCands.forEach(function (c) { var v = clearanceOf(c); if (v > ebv) { ebv = v; ebest = c; } });
  var eyeSz = clamp((yd[1] - yd[0]) * 0.055, 0.26, 0.62);
  drawEye(g, ebest[0], ebest[1], eyeSz);
  obstacles.push([[ebest[0] - eyeSz * 1.4, ebest[1]], [ebest[0] + eyeSz * 1.4, ebest[1]]]);

  /* ───── labels (drawn last, collision-aware, with halos) ───── */
  var L = g.group();
  var off = (fs * 1.0) / unit;

  placeLabel(L, [[-d - 0.55, h + 0.2], [-d - 0.2, h + 0.72], [-d + 0.55, h + 0.35], [-d - 0.8, h - 0.25]],
    'Q', '#111', fs, true, null, lblBox);

  var objHw = (6 * fs * 0.31) / unit;
  placeLabel(L, [[-d - 0.38 - objHw, h * 0.52], [-d - 0.38 - objHw, h * 0.82], [-d - 0.38 - objHw, h * 0.22]],
    'Object', '#111', fs * 0.95, false, null, lblBox);

  placeLabel(L, [[-d - 0.34, -off * 0.95], [-d + 0.34, -off * 0.95], [-d - 0.34, off * 0.95]],
    'P', '#111', fs, true, null, lblBox);

  var axisPts = [];
  if (inBox(Cp, box)) axisPts.push({ x: Cx, s: 'C' });
  if (inBox(Fp, box)) axisPts.push({ x: Fx, s: 'F' });
  if (xi > box.xlo && xi < box.xhi) axisPts.push({ x: xi, s: 'P\u2032' });
  axisPts.sort(function (A, B) { return A.x - B.x; });
  axisPts.forEach(function (it, k) {
    var up = (k % 2 === 0);
    var c = up
      ? [[it.x, off], [it.x, -off], [it.x, off * 2.15], [it.x, -off * 2.15]]
      : [[it.x, -off], [it.x, off], [it.x, -off * 2.15], [it.x, off * 2.15]];
    placeLabel(L, c, it.s, '#111', fs, true, null, lblBox);
  });

  /* V sits outside the arc, beside the vertex (as in the source) */
  var vx = (mode === 'concave') ? 0.55 : -0.55;
  placeLabel(L, [[vx, off * 0.55], [vx, -off * 0.55], [vx, off * 1.7], [vx, -off * 1.7]],
    'V', '#111', fs, true, null, lblBox);

  /* Q′ exactly at the ray crossing */
  if (tipVisible) {
    var qo = off * 1.15, qc = [];
    [[1, -0.55], [1, 0.55], [-1, -0.55], [-1, 0.55], [0.35, -1], [0.35, 1]].forEach(function (v) {
      qc.push([xi + v[0] * qo, hi + v[1] * qo]);
    });
    placeLabel(L, qc, 'Q\u2032', '#111', fs, true, null, lblBox);

    /* 'Image' label in clear space + curved leader to the image arrow */
    var cands = [], xLoC, xHiC, yLoC, yHiC;
    if (mode === 'concave') {
      xLoC = xi + 0.6; xHiC = Math.min(box.xhi - 0.9, xi + 3.2); yLoC = hi - 2.6; yHiC = hi - 0.8;
    } else {
      xLoC = xi - 1.2; xHiC = Math.min(box.xhi - 0.9, xi + 2.4); yLoC = -2.6; yHiC = -0.9;
    }
    for (cx = xLoC; cx <= xHiC + 1e-6; cx += Math.max(0.2, (xHiC - xLoC) / 6)) {
      for (cy = yLoC; cy <= yHiC + 1e-6; cy += Math.max(0.2, (yHiC - yLoC) / 5)) {
        if (cy < lblBox.ylo + 0.3 || cy > lblBox.yhi - 0.3) continue;
        if (mode === 'concave' && cx > mxf(clamp(cy, -yAp, yAp)) - 0.8) continue;
        cands.push([cx, cy]);
      }
    }
    if (!cands.length) cands.push([xi + 1.2, hi - 1.3]);
    var lbest = cands[0], lbv = -1;
    cands.forEach(function (c) {
      var v = clearanceOf(c);
      placedBoxes.forEach(function (b) {
        if (Math.abs(c[0] - b.x) < b.hw + 0.7 && Math.abs(c[1] - b.y) < b.hh + 0.4) v -= 1.4;
      });
      if (v > lbv) { lbv = v; lbest = c; }
    });
    var target = [xi + (lbest[0] > xi ? 0.1 : -0.1), hi * 0.75];
    leader(L, lbest, target, unit * 0.42);
    placeLabel(L, [lbest], 'Image', '#111', fs * 0.95, false, null, lblBox);
  }

  /* ray numerals — offset along each segment so they never collide */
  rays.forEach(function (r) {
    var c = COL[r.n], opa = rayGroups[r.n];
    var ng = L.group().opacity(opa);
    r.parts.forEach(function (p) {
      if (p.dash || !p.nf) return;
      var dx = p.b[0] - p.a[0], dy = p.b[1] - p.a[1], len = hyp(dx, dy);
      if (len < 0.5) return;
      var nx = -dy / len, ny = dx / len;
      if (ny < 0) { nx = -nx; ny = -ny; }
      var o = (fs * 0.82) / unit, cands = [];
      p.nf.forEach(function (t) {
        var px = p.a[0] + dx * t, py = p.a[1] + dy * t;
        cands.push([px + nx * o, py + ny * o]);
        cands.push([px - nx * o, py - ny * o]);
      });
      placeLabel(ng, cands, String(r.n), c, fs * 0.95, false, '700', lblBox);
    });
  });

  /* caption only — explanatory text lives in the side panel */
  txtAt(L, (xd[0] + xd[1]) / 2, yd[0] + (fs * 0.95) / unit,
    mode === 'concave' ? '(a) concave mirror' : '(b) convex mirror', '#111', fs * 0.95, 'middle');

  /* ---- panel readouts ---- */
  var st = document.getElementById('statusLine');
  if (st) {
    st.textContent = (mode === 'concave')
      ? 'Real, inverted image — the rays actually cross.'
      : 'Virtual, upright image — only the extensions cross.';
    st.style.color = (mode === 'concave') ? '#2c6e49' : '#8a5000';
  }
  var info = document.getElementById('imgInfo');
  if (info) {
    var msg = 'Object ' + (d / F0).toFixed(1) + 'f in front  ·  image ' +
      Math.abs(di / F0).toFixed(2) + 'f ' + (di > 0 ? 'in front (real)' : 'behind (virtual)') +
      '  ·  m = ' + m.toFixed(2) + (m < 0 ? ' (inverted)' : ' (upright)');
    var miss = [];
    if (!use2) miss.push('2');
    if (!use3) miss.push('3');
    if (miss.length) msg += '  —  ray ' + miss.join(' & ') + ' would strike far outside this finite mirror, so it is not drawn.';
    if (!tipVisible) msg += '  —  Q′ lies beyond the frame: as the object nears F the image races away.';
    info.textContent = msg;
  }
  window.__markRendered();
}

/* ───────── interactions ───────── */
function toggle_mirrorType(on) {
  state.mode = on ? 'convex' : 'concave';
  render();
}
function update_objectDistance(v) { state.s = v; render(); }
function selectRay(n) { state.sel = (state.sel === n) ? 0 : n; updateRuleUI(); render(); }

function updateRuleUI() {
  for (var k = 0; k <= 4; k++) {
    var b = document.getElementById('rayBtn' + k);
    if (b) b.className = (state.sel === k) ? 'active' : '';
  }
  var rb = document.getElementById('ruleBox');
  if (rb) rb.textContent = state.sel ? RULES[state.sel].l
    : 'All rays shown. Any two are enough to locate Q′ — the others confirm it.';
}

function keyIdea() {
  showPopup('Key idea',
    'An image is simply where the rays from a point on the object meet. If they meet in real space the image is real and inverted (concave mirror); if only their backward extensions meet, the image is virtual and upright behind the mirror (convex mirror).');
}

/* ───────── demo steps ───────── */
function goStep(i) {
  i = (i + STEPS.length) % STEPS.length;
  state.step = i;
  var st = STEPS[i];
  state.mode = st.mode; state.s = st.s; state.sel = st.sel;
  var cb = document.getElementById('mirrorTypeInput');
  if (cb) cb.checked = (state.mode === 'convex');
  var sl = document.getElementById('objectDistanceInput');
  if (sl) sl.value = state.s;
  var so = document.getElementById('objectDistanceVal');
  if (so) so.value = state.s;
  document.getElementById('demoNarration').textContent = st.n;
  document.getElementById('stepLabel').textContent = 'Step ' + (i + 1) + '/' + STEPS.length + ' — ' + st.t;
  updateRuleUI();
  render();
}
function nextStep() { goStep(state.step + 1); }
function prevStep() { goStep(state.step - 1); }

document.addEventListener('fig-resize', function () { render(); });
goStep(0);
